from collections.abc import Callable
from BaseClasses import CollectionRule, Entrance, CollectionState
from worlds.generic.Rules import set_rule
from typing import TYPE_CHECKING
from .Buttons import get_button_name
from .Macros import *

if TYPE_CHECKING:
    from . import GlyphsWorld

def connect_entrances(world: "GlyphsWorld"):
    player = world.player
    state = CollectionState(world.multiworld)

    if not world.macro_init:
        set_macro_rules(state, world)

    # Region Access
    # ----------------------from----------------to---------------------------------------------conditions--------------------------------
    connect_areas(world, "Menu",            "Region 1A",            lambda state: True)
    connect_areas(world, "Region 1A",       "Region 1C",            lambda state: True)
    connect_areas(world, "Region 1A",       "Region 1F",            lambda state: can_dash(state, player))
    connect_areas(world, "Region 1B",       "Region 1C",            lambda state: can_dash(state, player)                   and (can_wall_jump(state, world)    or can_press_buttons(state, player, world, ["R1B Lowest", "R1B 3rd Lowest", "R1B 6th Lowest"])) and can_press_buttons(state, player, world, ["R1B 4th Lowest", "R1B 5th Lowest"]))
    connect_areas(world, "Region 1B",       "Region 1E",            lambda state: defeated_runic_construct(state, player)   and can_wall_jump(state, world))
    connect_areas(world, "Region 1C",       "Region 1B",            lambda state: can_wall_jump(state, world))
    connect_areas(world, "Region 1C",       "Region 1D",            lambda state: can_press_button(state, player, world, "R1C First")   and (can_wall_jump(state, world)    or can_press_button(state, player, world, "R1C Second")))
    connect_areas(world, "Region 1C",       "Region 1F",            lambda state: False)    # with current flower puzzle implementation it makes this check inaccurate but it never actually comes into play
    if world.options.FlowerPuzzleSkips.value:
        world.multiworld.register_indirect_condition(world.get_region("Region 1E"),
            connect_areas(world, "Region 1D",       "Region 1B",            lambda state: can_press_button(state, player, world, "R1B Save")    and flower_puzzle_completion(state, player, world) >= 1)
        )
    connect_areas(world, "Region 1D",       "Region 1E",            lambda state: True)
    connect_areas(world, "Region 1E",       "Region 1B",            lambda state: defeated_runic_construct(state, player)   and can_dash(state, player))
    connect_areas(world, "Region 1E",       "Region 1D",            lambda state: can_dash(state, player))
    connect_areas(world, "Region 1F",       "Region 1A",            lambda state: can_dash(state, player))
    connect_areas(world, "Region 1F",       "Region 1C",            lambda state: True)
    connect_areas(world, "Region 1F",       "Region 2A",            lambda state: can_wall_jump(state, world)       or (can_dash(state, player) and can_press_button(state, player, world, "R1F Right")))
    connect_areas(world, "Region 2A",       "Region 1F",            lambda state: True)
    connect_areas(world, "Region 2A",       "Region 2B",            lambda state: can_dash(state, player)                   and can_press_buttons(state, player, world, ["R2A Gate Left", "R2A Upper"]))
    connect_areas(world, "Region 2B",       "Region 2E",            lambda state: can_dash(state, player))
    connect_areas(world, "Region 2B",       "Region 2L",            lambda state: True)
    connect_areas(world, "Region 2B",       "Region 2N",            lambda state: serpent_door_open(state, player, world))
    connect_areas(world, "Region 2B",       "The Between",          lambda state: can_dash(state, player))
    connect_areas(world, "Region 2C",       "Region 2D",            lambda state: True)
    connect_areas(world, "Region 2D",       "Region 2C",            lambda state: True) # needs to change when save button sanity is implemented
  # connect_areas(world, "Region 2E",       "Region 2B",            lambda state: True) # this actually doesnt work since the path is blocked off from this angle if you havn't visited the region before
    connect_areas(world, "Region 2E",       "Region 2D",            lambda state: can_dash(state, player)                   and can_press_buttons(state, player, world, ["R2E Lower", "R2D Save"])  and (get_button_color(world, "R2D Save") == ButtonColor.GREEN   or can_press_button(state, player, world, "R2E Upper Puzzle")))
    connect_areas(world, "Region 2E",       "Region 2F",            lambda state: can_dash(state, player)                   and can_press_button(state, player, world, "R2G Hidden"))
    connect_areas(world, "Region 2E",       "Region 2G",            lambda state: can_dash(state, player)                   and can_press_button(state, player, world, "R2G Lower"))
    connect_areas(world, "Region 2F",       "Region 2E",            lambda state: True)
    connect_areas(world, "Region 2F",       "Smile Shop",           lambda state: True)
    connect_areas(world, "Region 2G",       "Region 2F",            lambda state: can_dash(state, player)                   and can_press_button(state, player, world, "R2G Hidden"))
    connect_areas(world, "Region 2G",       "Region 2I",            lambda state: can_dash(state, player)                   and can_press_buttons(state, player, world, ["R2G Middle", "R2G Upper Right"])  and (can_parry(state, player)   or can_press_buttons(state, player, world, ["R2G Upper Left", "R2G Upper Middle"])))
    if world.options.FlowerPuzzleSkips.value:
        world.multiworld.register_indirect_condition(world.get_region("Region 1E"),
            connect_areas(world, "Region 2G",       "Region 2O",            lambda state: flower_puzzle_completion(state, player, world) >= 2)
        )
    connect_areas(world, "Region 2I",       "Region 2H",            lambda state: can_dash(state, player)                   and can_press_buttons(state, player, world, ["R2H Lower", "R2I Lower Left", "R2I Lower Middle", "R2I Upper Left", "R2I Upper Middle", "R2I Right"]))
    connect_areas(world, "Region 2I",       "Region 2J",            lambda state: can_wall_jump(state, world)       or (can_dash(state, player) and can_press_buttons(state, player, world, ["R2I Lower Left", "R2I Lower Middle", "R2I Right"])))
  # connect_areas(world, "Region 2J",       "Region 2I",            lambda state: can_chain_wall_jumps(state, player, world))   # logically will never be needed without save button sanity
    connect_areas(world, "Region 2J",       "Region 2K",            lambda state: shadow_chase_open(state, player, world))
    connect_areas(world, "Region 2L",       "Region 2M",            lambda state: can_dash(state, player)                   and can_press_buttons(state, player, world, ["R2L Right", "R2L Decent Upper Left", "R2L Decent Upper Right", "R2L Decent Upper Middle", "R2L Decent Middle", "R2L Decent Lower"])   and (get_button_color(world, "R2L Decent Middle") != ButtonColor.GREEN  or get_button_color(world, "R2L Decent Lower") != ButtonColor.GREEN or has_sword(state, player)))
    connect_areas(world, "Region 2L",       "Region 4A",            lambda state: wizard_true_defeat(state, player))
    connect_areas(world, "Region 2N",       "Region 2O",            lambda state: defeated_gilded_serpent(state, player)    and can_dash(state, player)                 and can_press_button(state, player, world, "R2N Chase 1"))
    connect_areas(world, "Region 2O",       "Region 2P",            lambda state: defeated_gilded_serpent(state, player))
    connect_areas(world, "Region 2P",       "Region 2O",            lambda state: defeated_gilded_serpent(state, player)    and can_dash(state, player))
    connect_areas(world, "Region 2P",       "Region 2Q",            lambda state: has_grapple(state, player)                and can_press_button(state, player, world, "R2P Left"))
    connect_areas(world, "Region 2Q",       "Region 3A",            lambda state: True)
    connect_areas(world, "Region 2Q",       "Dark Region A",        lambda state: can_dash(state, player))
    if world.options.FlowerPuzzleSkips.value:
        world.multiworld.register_indirect_condition(world.get_region("Region 1E"),
            connect_areas(world, "Region 3A",       "Region 2M",            lambda state: flower_puzzle_completion(state, player, world) == 3)
        )
    connect_areas(world, "Region 3A",       "Region 3B",            lambda state: can_dash(state, player)                   and has_grapple(state, player)              and can_press_button(state, player, world, "R3A Left"))
    connect_areas(world, "Region 3A",       "Region 3E",            lambda state: can_dash(state, player)                   and can_press_buttons(state, player, world, ["R3A Middle Upper", "R3A Middle Lower"]))
    connect_areas(world, "Region 3A",       "Region 3G",            lambda state: can_dash(state, player)                   and has_grapple(state, player))
    if world.options.FlowerPuzzleSkips.value:
        world.multiworld.register_indirect_condition(world.get_region("Region 1E"),
            connect_areas(world, "Region 3A",       "Region 4F",            lambda state: can_press_button(state, player, world, "R4F Save")  and flower_puzzle_completion(state, player, world) == 3)
        )
    connect_areas(world, "Region 3B",       "Region 3C",            lambda state: can_dash(state, player))
    connect_areas(world, "Region 3C",       "Region 3D",            lambda state: can_dash(state, player)                   and has_grapple(state, player)              and can_press_buttons(state, player, world, ["R3C Left", "R3C Middle", "R3C Right", "R3C Gate Right"]))
    connect_areas(world, "Region 3E",       "Region 3F",            lambda state: can_dash(state, player)                   and has_grapple(state, player)              and can_press_buttons(state, player, world, ["R3E Upper", "R3E Lower Room 1", "R3E Lower Room 2", "R3E Lower Room 3"]))
    connect_areas(world, "Region 3E",       "Collapse",             lambda state: can_dash(state, player)                   and has_grapple(state, player)              and collapse_available(state, player)   and can_press_button(state, player, world, "R3E Upper"))
    connect_areas(world, "Region 3G",       "Region 3H",            lambda state: can_dash(state, player)                   and has_grapple(state, player)              and can_press_button(state, player, world, "R3G Right") and ((get_button_color(world, "R3G Right") == ButtonColor.GREEN and has_sword(state, player))   or can_press_button(state, player, world, "R3G Left")))
    connect_areas(world, "Region 3H",       "Region 3I",            lambda state: can_dash(state, player)                   and has_grapple(state, player)              and can_press_buttons(state, player, world, ["R3H Left", "R3H Middle", "R3H Right", "R3H Gate Left"]))
    connect_areas(world, "Region 4A",       "Region 4B",            lambda state: can_dash_attack(state, player)            and has_grapple(state, player)              and can_press_buttons(state, player, world, ["R4A Left", "R4A Middle", "R4A Right"]))
    connect_areas(world, "Region 4B",       "Region 4C",            lambda state: defeated_spearman(state, player))
    connect_areas(world, "Region 4C",       "Region 4D",            lambda state: can_dash(state, player)                   and has_grapple(state, player)              and (get_button_color(world, "R4C 4th") != ButtonColor.PINK or can_press_button(state, player, world, "R4C 3rd"))   and (get_button_color(world, "R4C 5th") == ButtonColor.GREEN    or can_press_button(state, player, world, "R4C 6th"))   and (get_button_color(world, "R4C 9th") != ButtonColor.PINK or can_press_button(state, player, world, "R4C 10th"))  and can_press_buttons(state, player, world, ["R4C 1st", "R4C 2nd", "R4C 4th", "R4C 5th", "R4C 7th", "R4C 8th", "R4C 9th", "R4C 5 Parry 1", "R4C 5 Parry 2", "R4C 5 Parry 3", "R4C 5 Parry 4", "R4C 5 Parry 5", "R4C Gate Right"]))
    connect_areas(world, "Region 4D",       "Region 4E",            lambda state: can_dash(state, player)                   and can_press_button(state, player, world, "R4E Save"))
    connect_areas(world, "Region 4D",       "Region 4G",            lambda state: can_dash(state, player)                   and has_grapple(state, player)              and can_parry(state, player)                    and (can_wall_jump(state, world)    or can_press_buttons(state, player, world, ["R4D Main Route 2nd", "R4D Main Route 3rd", "R4D Main Route 4th"])) and (get_button_color(world, "R4D Main Route 5th") == ButtonColor.GREEN or can_press_button(state, player, world, "R4D Main Route 6th"))    and can_press_buttons(state, player, world, ["R4D Main Route 1st", "R4D Main Route 5th"]))
    connect_areas(world, "Region 4G",       "Region 4F",            lambda state: True)
    connect_areas(world, "Region 4G",       "Region 4H",            lambda state: can_dash(state, player)                   and has_grapple(state, player)              and can_press_buttons(state, player, world, ["R4F Lower", "R4G 1st", "R4G 2nd", "R4G 3rd", "R4G 4th", "R4G 5th", "R4G 6th"]))
    connect_areas(world, "Region 4H",       "Region 4I",            lambda state: can_dash(state, player)                   and has_grapple(state, player)              and can_press_button(state, player, world, "R4H Middle"))
    connect_areas(world, "Region 4I",       "Region 4J",            lambda state: can_dash(state, player)                   and can_press_buttons(state, player, world, ["R4I Left", "R4I Right", "R4I Gate Upper"]))
    connect_areas(world, "Smile Shop",      "Region 1C",            lambda state: True)
    connect_areas(world, "Dark Region A",   "Dark Region B",        lambda state: can_dash(state, player)                   and has_grapple(state, player)              and defeated_null(state, player)    and can_press_buttons(state, player, world, ["Dark 1", "Dark 2", "Dark 3", "Dark 4", "Dark 5", "Dark 6", "Dark Save"]))
    connect_areas(world, "The Between",     "Region 2B",            lambda state: can_dash(state, player))
    connect_areas(world, "The Between",     "Smile Shop",           lambda state: can_dash(state, player))
    connect_areas(world, "Menu",            "Act 1",                lambda state: act_1_available(state, player))
    connect_areas(world, "Menu",            "Act 2",                lambda state: act_2_available(state, player))
    connect_areas(world, "Menu",            "Act 3",                lambda state: act_3_available(state, player))
    connect_areas(world, "Act 1",           "Epilogue",             lambda state: can_dash(state, player)                   and has_grapple(state, player)              and state.has("Shroud", player)   and can_press_button(state, player, world, "Epilogue 1"))


def set_rules(world: "GlyphsWorld"):
    player = world.player
    options = world.options
    state = CollectionState(world.multiworld) 

    if not world.macro_init:
        set_macro_rules(state, world)

    # Locations
    # ---------------------------------------------location_name------------------------------------------------conditions---------------------------------------------------------

    # Event Locations
    set_rule_from_string(world, "Defeat Runic Construct",                           lambda state: can_fight(state, world))
    set_rule_from_string(world, "Stalker Sigil 1",                                  lambda state: stalker_sigils_present(state, player))
    set_rule_from_string(world, "Serpent Lock 1",                                   lambda state: can_dash(state, player)                   and can_press_buttons(state, player, world, ["R2E Lower", "R2E Upper", "R2E Serpent Lock 1"]))
    set_rule_from_string(world, "Serpent Lock 2",                                   lambda state: can_dash(state, player)                   and can_press_button(state, player, world, "R2H Serpent Lock 2"))
    set_rule_from_string(world, "Serpent Lock 3",                                   lambda state: can_press_button(state, player, world, "R2M Serpent Lock 3"))
    set_rule_from_string(world, "Defeat Gilded Serpent",                            lambda state: can_dash(state, player)                     and can_fight(state, world)               and can_press_button(state, player, world, "R2N Chase 1"))
    set_rule_from_string(world, "Stalker Sigil 2",                                  lambda state: stalker_sigils_present(state, player))
    set_rule_from_string(world, "Stalker Sigil 3",                                  lambda state: stalker_sigils_present(state, player))
    set_rule_from_string(world, "Solve Flower Puzzle",                              lambda state: flower_puzzle_completion(state, player, world) == 3)
    set_rule_from_string(world, "Collapse Unlock",                                  lambda state: can_dash(state, player)                     and wizard_fight_available(state, world)    and can_fight(state, world)                       and has_grapple(state, player)  and can_press_button(state, player, world, "R3E Upper"))
    set_rule_from_string(world, "Wizard True Defeat",                               lambda state: can_dash_attack(state, player)              and wizard_fight_available(state, world)    and can_fight(state, world)                       and has_grapple(state, player)  and can_press_button(state, player, world, "R3E Upper"))
    set_rule_from_string(world, "Defeat Spearman",                                  lambda state: can_dash_attack(state, player)              and can_fight(state, world))
    set_rule_from_string(world, "Good Ending",                                      lambda state: can_fight(state, world)             and can_dash_attack(state, player)                  and can_parry(state, player)                              and wraith_fight_available(state, world)            and state.has("Gold Shard", player, 3))
    set_rule_from_string(world, "Last Fracture",                                    lambda state: has_clarity(state, player)                  and wraith_fight_available(state, world)    and state.has("Good Ending", player))
    set_rule_from_string(world, "False Ending",                                     lambda state: can_dash(state, player)                     and has_grapple(state, player)                      and can_press_button(state, player, world, "R2A Gate Right")  and state.can_reach_region("Region 2B", player)) # need to check for this specific region because if one specific screen has not been reached then the collapse is impossible
    set_rule_from_string(world, "Smilemask Ending",                                 lambda state: state.has("Smile Token", player, 10))
    set_rule_from_string(world, "Defeat Null",                                      lambda state: can_dash_attack(state, player)              and has_grapple(state, player)                      and can_press_buttons(state, player, world, ["Dark 1", "Dark 2", "Dark 3", "Dark 4", "Dark 5", "Dark 6", "Dark Save"]))
    set_rule_from_string(world, "Clarity",                                          lambda state: state.has("Rune Cube", player, 3))
    set_rule_from_string(world, "Perfect Clarity",                                  lambda state: state.has("Rune Cube", player, 3)           and (state.has("Shroud", player)                    or state.has("Progressive Essence of George", player)))
    set_rule_from_string(world, "Omnipotence Ending",                               lambda state: can_dash(state, player)                     and void_gate_open(state, player))
    set_rule_from_string(world, "Clear Act 1",                                      lambda state: void_gate_open(state, player)               and can_dash(state, player)                       and has_grapple(state, player)                              and state.has("Shroud", player) and can_press_buttons(state, player, world, ["Void Chase 1", "Void Chase 2", "Void Chase 3", "Void Chase 4", "Void Chase Gate"]))
    set_rule_from_string(world, "Clear Act 2",                                      lambda state: has_sword(state, player)                    and can_dash_attack(state, player)                  and (state.has("Shroud", player)                           or state.has("Progressive Essence of George", player, 1))  and can_parry(state, player)    and state.has("Gold Shard", player, 1))
    set_rule_from_string(world, "True Ending",                                      lambda state: can_fight(state, world)             and can_parry(state, player)                        and (state.has("Shroud", player)                           or state.has("Progressive Essence of George", player, 1))  and state.has("Gold Shard", player, 3))
    set_rule_from_string(world, "Epilogue Ending",                                  lambda state: can_dash(state, player)                     and state.has("Shroud", player)                     and state.has("Progressive Essence of George", player, 1) and state.has("Silver Shard", player, 15))

    # Region 1
    set_rule_from_string(world, "(R1) Starting Item",                               lambda state: True)
    set_rule_from_string(world, "(R1) Sword Pedestal",                              lambda state: True)
    set_rule_from_string(world, "(R1) Runic Construct Reward",                      lambda state: defeated_runic_construct(state, player))
    set_rule_from_string(world, "(R1) Map Pedestal",                                lambda state: can_dash(state, player)                   and can_press_button(state, player, world, "R1B Map Room"))
    set_rule_from_string(world, "(R1) Silver Shard Puzzle 1 - Map",                 lambda state: can_dash(state, player)                   and can_press_button(state, player, world, "R1B Upper Puzzle")  and (get_button_color(world, "R1B Upper Puzzle") == ButtonColor.BLACK   or can_press_button(state, player, world, "R1B Save")))
    set_rule_from_string(world, "(R1) Silver Shard Puzzle 2 - Grapple",             lambda state: can_dash(state, player)                   and has_grapple(state, player))
    set_rule_from_string(world, "(R1) Silver Shard Puzzle 3 - Spike Tunnel",        lambda state: can_dash(state, player))
    set_rule_from_string(world, "(R1) Smile Token Puzzle 1 - Hidden Bounce Pad",    lambda state: can_dash(state, player)                   and has_grapple(state, player))
    set_rule_from_string(world, "(R1) Smile Token Puzzle 9 - Moving Platforms",     lambda state: can_wall_jump(state, world)       or (can_dash(state, player) and can_press_buttons(state, player, world, ["R1B Lower Puzzle", "R1B Lowest"])))
    set_rule_from_string(world, "(R1) Color Cypher Room Pickup",                    lambda state: can_dash(state, player))
    set_rule_from_string(world, "(R1) Master Puzzle 2 - Silence",                   lambda state: can_dash(state, player)                   and has_grapple(state, player))


    # Region 2
    set_rule_from_string(world, "(R2S1) Silver Shard Puzzle 4 - Save Button",       lambda state: can_press_button(state, player, world, "R2D Save"))
    set_rule_from_string(world, "(R2) Silver Shard Puzzle 5 - Respawn",             lambda state: can_dash(state, player)                   and state.can_reach_region("Region 2B", player)) # change this to being able to access certain save buttons one save button sanity is implemented
    set_rule_from_string(world, "(R2) Silver Shard Puzzle 6 - Invisible",           lambda state: can_dash(state, player)                   and can_press_button(state, player, world, "R2B Puzzle"))
    set_rule_from_string(world, "(R2S2) Silver Shard Puzzle 7 - Timed",             lambda state: can_dash(state, player)                   and can_press_buttons(state, player, world, ["R2G Middle", "R2G Moving Platform"])  and (can_parry(state, player)   or (get_button_color(world, "R2G Upper Middle") != ButtonColor.BLACK    and can_press_buttons(state, player, world, ["R2G Upper Left", "R2G Upper Middle"]))))
    set_rule_from_string(world, "(R2) Silver Shard Puzzle 8 - Avoid Respawn",       lambda state: can_dash(state, player)                   and has_grapple(state, player)  and can_press_button(state, player, world, "R2P Puzzle"))
    if world.options.DashPuzzlesSolved.value:
        set_rule_from_string(world, "(R2) Silver Shard Puzzle 9 - Color Dash Puzzle",   lambda state: can_dash(state, player))
    else:
        set_rule_from_string(world, "(R2) Silver Shard Puzzle 9 - Color Dash Puzzle",   lambda state: can_dash(state, player)                   and state.can_reach_location("(R1) Color Cypher Room Pickup", player))
    set_rule_from_string(world, "(R2) Silver Shard Puzzle 15 - Escape Serpent",     lambda state: can_dash(state, player)                   and can_press_button(state, player, world, "R2N Chase 1")   and (defeated_gilded_serpent(state, player)                             or can_fight(state, world)))
    set_rule_from_string(world, "(R2S2) Smile Token Puzzle 3 - Car Hall",           lambda state: can_dash(state, player))
    set_rule_from_string(world, "(R2) Smile Token Puzzle 6 - Above Serpent",        lambda state: can_dash(state, player)                   and defeated_gilded_serpent(state, player)          and can_press_button(state, player, world, "R2N Save"))
    set_rule_from_string(world, "(R2S1) Smile Token Puzzle 8 - Erosion",            lambda state: can_dash(state, player)                   and can_press_button(state, player, world, "R2E Lower"))
    set_rule_from_string(world, "(R2S2) Smile Token Puzzle 10 - Chaos",             lambda state: can_dash(state, player)                   and has_grapple(state, player)  and can_press_buttons(state, player, world, ["R2K Chase Hidden", "R2K Chaos Upper 1", "R2K Chaos Upper 2", "R2K Chaos Upper 3", "R2K Chaos Upper 4", "R2K Chaos Middle 1", "R2K Chaos Middle 2", "R2K Chaos Middle 3", "R2K Chaos Middle 4", "R2K Chaos Middle 5", "R2K Chaos Lower 1", "R2K Chaos Lower 2", "R2K Chaos Lower 3", "R2K Chaos Lower 4", "R2K Chaos Lower 6", "R2K Chaos Pivot 1", "R2K Chaos Pivot 2", "R2K Chaos Gate Left"]))
    set_rule_from_string(world, "(R2) Gilded Serpent Reward",                       lambda state: True)
    set_rule_from_string(world, "(R2S1) Cameo Room Pickup",                         lambda state: can_dash(state, player))
    set_rule_from_string(world, "(R2S2) Car Hall Pickup",                           lambda state: can_dash(state, player)                   and can_press_button(state, player, world, "R2H Save"))
    set_rule_from_string(world, "(R2S1) Near Shooters Pickup",                      lambda state: can_dash(state, player)                   and can_press_button(state, player, world, "R2E Lower"))
    set_rule_from_string(world, "(R2S3) Collapsed Tunnel Pickup",                   lambda state: True)
    set_rule_from_string(world, "(R2) Nest Room Pickup",                            lambda state: can_dash(state, player))
    set_rule_from_string(world, "(R2) Serpent Boss Room Pickup",                    lambda state: can_wall_jump(state, world)       or (can_dash(state, player)                         and state.can_reach_region("Region 2N", player)                         and can_press_buttons(state, player, world, ["R2N Chase 1", "R2N Chase 2"])                  and defeated_gilded_serpent(state, player)))
